import re

def split_fields(line):
    def fix_match(m):
        s = m.group()
        if s.startswith('"') and s.endswith('"'):
            s = s[1:-1]
            s = s.replace('""', '"')
        return s

    line = re.sub(r'([^\\]"|\\)",', fix_match, line)
    return re.split(r',(?=(?:[^\"]*"[^\"]*")*[^\"]*$)', line)
