import re

def split_fields(line):
    fields = []
    regex = re.compile(r'"([^"\\]*(\\.[^"\\]*)*)"|([^,]+)')
    for match in regex.finditer(line):
        if match.group(1) is not None:
            fields.append(match.group(1).replace('""', '"'))
        elif match.group(3) is not None:
            fields.append(match.group(3))
    return fields
