def split_fields(line):
    fields = []
    state = 0  # 0: normal, 1: in double quote
    field = ""
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if state == 0:
            if c == '"':
                state = 1
            elif c == ',':
                fields.append(field)
                field = ""
            else:
                field += c
        elif state == 1:
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    field += '"'
                    i += 1
                else:
                    state = 0
            else:
                field += c
        i += 1
    if state == 1:
        raise ValueError("Unmatched double quote in CSV line")
    fields.append(field)
    return fields
