import re

def split_fields(line):
    fields = []
    field_re = re.compile(r'\"([^\"]*(?:\""[^\"]*)*)\"|([^,]+)')
    for match in field_re.finditer(line):
        if match.group(1):
            fields.append(match.group(1).replace('""', '"'))
        else:
            fields.append(match.group(2))
    return fields
