import re

def split_fields(line):
    pattern = re.compile(r'"([^"]*(?:""[^"]*)*)"|([^,]+)', re.DOTALL)
    fields = []
    for match in pattern.finditer(line):
        if match.group(1) is not None:
            field = match.group(1).replace('""', '"')
        else:
            field = match.group(2)
        fields.append(field)
    return fields
