def split_fields(line):
    fields = []
    field = ""
    in_quotes = False

    for char in line:
        if char == '"':
            if in_quotes:
                if len(field) > 0 and field[-1] == '"':
                    field = field[:-1]
                else:
                    in_quotes = False
            else:
                in_quotes = True
        elif char == ',' and not in_quotes:
            fields.append(field)
            field = ""
        else:
            field += char

    if len(field) > 0:
        fields.append(field)

    return fields
