def split_fields(line):
    # Helper function to unescape double quotes in a quoted field
    def unescape_quotes(field):
        return field.replace('""', '"')

    # Initialize variables
    fields = []
    in_quotes = False
    current_field = []

    # Iterate through each character in the line
    for char in line:
        if char == '"':
            # Toggle quote state
            in_quotes = not in_quotes
        elif char == ',' and not in_quotes:
            # End of a field, add to list and reset
            fields.append(''.join(current_field))
            current_field = []
        else:
            # Add character to current field
            current_field.append(char)

    # Add the last field if it exists
    if current_field:
        fields.append(''.join(current_field))

    #Post-process quoted fields to unescape double quotes
    for i in range(len(fields)):
        if re.match(r'^"(.*)"$', fields[i]):
            fields[i] = unescape_quotes(fields[i][1:-1])

    return fields
